def esc(v: Any) -> str:
    return html.escape(str(v if v is not None else "—"), quote=True)


def digest(p: Path) -> str:
    return hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else "UNKNOWN"


def read_json(p: Path) -> dict[str, Any]:
    try:
        raw = p.read_text(errors="replace").strip()
        value = json.loads(raw)
        return json.loads(value) if isinstance(value, str) else value
    except Exception:
        return {}


def md_table(headers: list[str], rows: list[list[Any]]) -> str:
    out = ["| " + " | ".join(headers) + " |", "| " + " | ".join("---" for _ in headers) + " |"]
    for row in rows:
        out.append("| " + " | ".join(str(x).replace("\n", " ").replace("|", "\\|") for x in row) + " |")
    return "\n".join(out)


def html_table(headers: list[str], rows: list[list[Any]]) -> str:
    head = "<tr>" + "".join(f"<th>{esc(x)}</th>" for x in headers) + "</tr>"
    body = "".join("<tr>" + "".join(f"<td>{esc(x)}</td>" for x in row) + "</tr>" for row in rows)
    return f"<div class='table-wrap'><table><thead>{head}</thead><tbody>{body}</tbody></table></div>"


def screenshot_records() -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for p in sorted(EVIDENCE_DIR.glob("*.png")):
        m = re.match(r"(E\d+)-(.+)-(es|en)-(dark|light)-(\d+)x(\d+)(?:-.+)?$", p.stem)
        if not m:
            continue
        eid, label, locale, theme, w, h = m.groups()
        if "dashboard" in label:
            surface, journey = "DASHBOARD/SHELL", "J20"
        elif "generator" in label:
            surface, journey = "WORKOUT_GENERATION", "J07"
        elif "workout-review" in label:
            surface, journey = "WORKOUT_REVIEW", "J08"
        elif "workout-execution" in label:
            surface, journey = "WORKOUT_EXECUTION", "J10"
        elif "exercise-detail" in label:
            surface, journey = "EXERCISE_DETAIL", "J14"
        elif "exercises" in label or "exercise-search" in label:
            surface, journey = "EXERCISE_LIBRARY", "J13"
        elif "progress" in label:
            surface, journey = "PROGRESS", "J15"
        elif "nutrition" in label:
            surface, journey = "NUTRITION", "J16"
        elif "achievements" in label:
            surface, journey = "GAMIFICATION", "J18"
        else:
            surface, journey = "APPLICATION", "J20"
        obs = read_json(p.with_suffix(".observation.json"))
        records.append({
            "id": eid, "type": "SCREENSHOT", "environment": "PRODUCTION", "surface": surface,
            "journey": journey, "viewport": f"{w}×{h}", "theme": theme, "locale": locale,
            "url": obs.get("url", "https://impulso.anclora.com"),
            "action": "Open route, await network idle, capture rendered state",
            "description": f"Current production {label.replace('-', ' ')} state with shell and route content.",
            "path": str(p.relative_to(ROOT)),
        })
    return records


def make_finding(fid: str, title: str, scope: str, surface: str, journey: str, screen: str,
                 severity: str, priority: str, evidence: str, cause: str, impact: str,
                 recommendation: str, historical: str | None = None, category: str = "Product UX",
                 criticality: str = "HIGH", friction: str = "CONTEXT_LOAD", quick: bool = False) -> dict[str, Any]:
    return {
        "id": fid, "title": title, "category": category, "finding_scope": scope, "surface": surface,
        "journey": journey, "screen": screen, "user_type": "ACTIVE_USER", "task_criticality": criticality,
        "friction_type": friction, "severity": severity, "priority": priority,
        "evidence_level": "MEASURED_BROWSER + MEASURED_CODE", "browser_environment": "PRODUCTION",
        "evidence": evidence, "frequency": "Recurring for the affected journey", "current_behavior": evidence,
        "root_ux_cause": cause, "why_it_matters": "The user must act under time, attention and recovery constraints.",
        "user_impact": impact, "recommended_change": recommendation,
        "why_this_change": "It reduces friction while preserving the current capability contract.",
        "expected_benefit": "Clearer task completion and higher confidence.", "effort": "LOW" if quick else "MEDIUM",
        "risk": "LOW" if quick else "MEDIUM", "quick_win": quick, "dependencies": "Targeted UX/accessibility regression coverage",
        "do_not_break": "Existing successful route, state persistence and primary actions", "historical_id": historical,
        "change_class": "RETESTED" if historical else "NEW", "implementation_guidance": recommendation,
    }


