def write_md(r: dict[str, Any]) -> None:
    m, f = r["metadata"], r["findings"]
    lines = ["# Anclora Impulso — Deep UX/UI Product Re-Audit", "", f"**AUDIT_REVISION:** `{m['audit_revision']}`  ", f"**STATUS:** `{m['status']}`", "", "## Audit metadata", md_table(["Field","Value"], [[k, ", ".join(v) if isinstance(v,list) else v] for k,v in m.items()]), "", "## 00 Index", "", "This is a deep remediation of the previous Impulso audit, not an independent report. It reuses valid evidence and expands current authenticated product coverage with real production browser screenshots."]
    index = ["01 Executive assessment","02 What changed","03 Methodology delta and depth gap","04 Surface classification and product model","05 Promise versus observed","06 User types and task inventory","07 Critical journeys","08 Screen map and experience map","09 Landing and authentication","10 Onboarding","11 Workout generation and review","12 Workout execution","13 Mobile workout ergonomics","14 Exercise library and detail","15 Progress","16 Nutrition","17 Gamification","18 AI personalization and trust","19 Application shell","20 Primary workspaces","21 Viewport economy","22 Action hierarchy","23 System states","24 Error recovery","25 Responsive","26 Light and dark","27 Accessibility","28 Internationalization","29 Premium surface","30 Anti-template and memorability","31 Historical regression matrix","32 Scorecards","33 What works well","34 Product UX/access findings","35 Engineering/compliance scope","36 Quick wins","37 Structural opportunities","38 Roadmap","39 DO_NOT_BREAK","40 Evidence coverage","41 Tool compatibility","42 Limitations","43 Final comparative answer"]
    lines += ["", "## Contents", "", "\n".join(f"{i+1}. {x}" for i,x in enumerate(index))]
    lines += ["", "## 01 Executive assessment", "", "### Current verdict", "The audit is materially deeper than the previous artifact: canonical auth/session now pass, private production routes are captured in desktop and mobile viewports, and workout execution is analyzed as a real fitness workflow. Status remains `PASS_WITH_JUSTIFIED_GAPS` because safety rules prevented writes and fixture-sensitive tests.", "", md_table(["Question","Evidence-backed answer"], [["BIGGEST_USER_FRICTION","Long repeated workout set ledger without persistent current-exercise focus."],["BIGGEST_SIMPLIFICATION_OPPORTUNITY","Make workout execution a focused session workspace."],["BIGGEST_COGNITIVE_LOAD_OPPORTUNITY","Reduce repeated field scanning and cross-surface card interpretation."],["BIGGEST_QUICK_WIN","Unique per-set accessible names and fieldsets."],["BIGGEST_STRUCTURAL_OPPORTUNITY","Mobile-first workout focus + safe exit/resume."],["BIGGEST_PREMIUM_UI_OPPORTUNITY","Unify copper identity and reduce accent/card fragmentation."],["BIGGEST_VIEWPORT_ECONOMY_OPPORTUNITY","Keep current exercise, timer/progress and primary set action above fold at 390×844."],["BIGGEST_AI_TRUST_OPPORTUNITY","Inputs-used summary plus rationale/regenerate/undo."],["BIGGEST_MOBILE_WORKOUT_OPPORTUNITY","Thumb-reachable frequent actions without global-nav interruption."],["OVERALL","Good foundation and operational core; fair-to-good active fitness UX until focus, semantics and AI control improve."]])]
    lines += ["", "## 02 What changed", "", "The previous artifact contained seven saved screenshots and aggregated private observation E12. This remediation preserves prior records with context, adds current production route captures, measures viewports, and creates a deep journey/screen/evidence index. The repository HEAD remains unchanged; CORS remediation is an already-deployed runtime observation, not a product-code change.", "", "### Evidence reuse", md_table(["Material","Classification","Reason"], [["CORS preflight/health","REUSABLE_WITH_CONTEXT","Retested after runtime remediation; F-01 status changed."],["Public landing/auth captures","REUSABLE_WITH_CONTEXT","Still current production."],["Preview private E12","REUSABLE_WITH_CONTEXT","Context only; current production captures replace aggregation."],["Missing private mobile captures","INSUFFICIENT","Now added at 390×844 and 430×932."],["Static runtime output","REUSABLE_WITH_CONTEXT","Code/context only, never browser coverage."]]), "", "### DEPTH_GAP_MATRIX", md_table(["AREA","CURRENT","TALENT TARGET","GAP","WHY","NEW EVIDENCE","OUTPUT"], r["depth_gap_matrix"])]
    lines += ["", "## 03 Methodology delta", "", "The installed contractual skill is v1.5.0 while `skill.yaml` and runtime manifest metadata report v1.4.0. The current SKILL.md wins. Browser environment is explicitly PRODUCTION. `COMPLETED != COVERED`; writes and non-observable states remain partial or not evaluated.", "", "## 04 Surface classification and product model", md_table(["Field","Result","Source"], [["PRIMARY_SURFACE","APPLICATION","Route inventory + private browser evidence"],["SURFACE_MODE","APPLICATION","Auto-detect reconciled with code/browser"],["PLATFORM_MODE","PWA","Manifest/app shell; offline unknown"],["SECONDARY_SURFACES","LANDING_PAGE","/landing"],["DOMAIN_PROFILE","FITNESS","Workout/progress/nutrition/exercises/motivation"],["ENVIRONMENT","PRODUCTION","Current deep pass"],["MISMATCH","DOCUMENTED","Heuristic may say DASHBOARD"]]), "", md_table(["Capability","Classification","Evidence"], [["Auth/session","CONFIRMED_FUNCTIONAL","B01-B05"],["Dashboard/shell","CONFIRMED_FUNCTIONAL","E13/E19/E29/E36/E55"],["Workout generation","CONFIRMED_RENDERED; write blocked","E14/E56 + code"],["Workout execution","CONFIRMED_RENDERED; completion blocked","E26-E28/E35/E42/E48/E52/E60"],["Exercises","CONFIRMED_FUNCTIONAL_READONLY","E15/E31/E38/E53/E54"],["Progress","CONFIRMED_RENDERED","E16/E58"],["Nutrition","CONFIRMED_RENDERED","E17/E59"],["Gamification","CONFIRMED_RENDERED","E18/E41"],["PWA/offline","DECLARED_DOCS / UNKNOWN","Manifest only"],["Admin","CODE_ONLY / SAFETY_BLOCKED","Not authorized"]])]
    lines += ["", "## 05 Promise versus observed", md_table(["PROMISE","OBSERVED","EVIDENCE","CONFIDENCE"], [["Personalization","Profile proposal and broad 40+ rationale; result controls not observed","E14/E56","MEDIUM"],["Workout execution","12-set session with rest/notes/finish; long-form concern","E26/E35/E60","HIGH"],["Progress","KPIs/recommendation/charts; low-data history","E16/E58","HIGH"],["Nutrition","Daily state and plan/log actions; no write","E17/E59","MEDIUM"],["Motivation","XP/achievements visible; longitudinal meaning unknown","E18/E41","MEDIUM"],["Premium","Strong dark/copper base; accents/density reduce polish","E01-E04/E55/E60","MEDIUM"],["PWA","Manifest declared; no offline proof","Code/manifest","LOW"],["ES/EN","Private visible copy switches; document lang drift","E19/E36/B07","HIGH"],["Accessibility","Named shell/forms; repeated set semantics incomplete","E26/E35/code","MEDIUM"]])]
    lines += ["", "## 06 User types and task inventory", md_table(["USER_TYPE","PRIMARY_GOAL","ENTRY","WORKSPACE","NEXT_ACTION","RECOVERY"], r["user_types"]), "", md_table(["ID","TASK","CLASS","CRITICALITY","COVERAGE"], r["tasks"])]
    lines += ["", "## 07 Critical journeys", "", "The prior full-schema journey records are retained and now linked to current screenshots where applicable.", "", md_table(["ID","NAME","ROUTE","COVERAGE","SCREENSHOTS"], [[j.get("id"),j.get("name"),j.get("route"),j.get("coverage"),", ".join(j.get("screenshot_reference",[]))] for j in r["journeys"]]), "", "### Workout execution record", "Entry: existing plan. Goal: complete sets with divided attention. Route: `/workouts/:id/start`. Inputs: reps, weight, RIR, RPE, rest and notes. Decisions: mark vs rest, exit vs finish. Wait/loading: workout/image load; rest timer not activated. Disabled: completion-state behavior not invoked. Success: session screen and explicit finish action. Error: no induced fault. Recovery: exit and keep draft; local draft was cleared after observation. Viewports: 1440×900, 390×844, 430×932, 1920×1080. Themes/locales: light/dark, ES/EN. Coverage: `COVERED_READONLY` / `BLOCKED_WRITE` for completion."]
    lines += ["", "## 08 Screen map and experience map", md_table(["SCREEN","PURPOSE","PRIMARY","SECONDARY","DESTRUCTIVE","USER_TYPE","ENTRY","EXIT","RECOVERY"], r["screen_map"]), "", md_table(["STAGE","ENTRY","GOAL","ACTION","RESPONSE","FRICTION","RESULT","RECOVERY"], r["experience_map"])]
    lines += ["", "## 09 Landing and authentication", "", "The canonical domain now passes the previously blocking auth path: preflight 204, API health 200, credential login to dashboard, refresh persistence and logout. F-01 is therefore `VERIFIED_FIXED`. The public root/landing split and login/signup provider asymmetry remain current findings. OAuth entry was inspected read-only and not launched.", "", "## 10 Onboarding", "", "Source and prior CUA observation confirm a three-step onboarding dialog collecting context, base data, objective and limitations. The authorized profile-complete account did not expose first-use onboarding in the isolated browser session; no real profile write was attempted. This is `NOT_RETESTED`, not a negative score.", "", "## 11 Workout generation and review", "", "The generator is substantive: saved plans, profile proposal, 40+ rationale, type/duration/difficulty/environment, target muscles, equipment and AI CTA. Review shows title, exercise list, delete and start. Generation/delete were blocked writes; result rationale, regeneration, undo and error/wait states remain open.", "", "## 12 Workout execution", "", "The page renders four exercises and 12 set rows with reps, weight, RIR, RPE, rest, mark/rest controls, progress, notes and exit/finish. On mobile, the title, 0/12 progress, rest card and first exercise occupy the first view; later sets require scrolling. The problem is not missing capability but focus/context during physical use.", "", md_table(["MEASURE","OBSERVED","IMPLICATION"], [["Sets","12 loaded rows","Repeated scanning"],["Scroll","Later exercise groups below 390×844 fold","High divided-attention burden"],["Targets","Touch-sized controls","Context ambiguity remains"],["Timer","Rest card visible; live timer not activated","Later persistence unknown"],["Next set","Mark local to row; no explicit next focus","Opportunity for focused state"],["Completion","Not invoked","Write boundary"]])]
    lines += ["", "## 13 Mobile workout ergonomics", "", "The current mobile shell uses a top hamburger; in-workout controls are local, but global actions require a drawer/context switch. A bottom nav is not assumed to be universally better. The evidence supports a focused session action bar, safe exit/resume semantics and unique set control context. The answer to 'can a person train without fighting the UI?' is `PARTLY_SUPPORTED`, not certified: touch targets are visible, but long scroll and repeated context remain material.", "", "## 14 Exercise library and detail", "", "The library exposes a 479/485-scale dataset, four filters, search, virtualized results and a same-route detail dialog. Synthetic search produced 17 results; detail exposed description, target muscles and instructions. Repeated unavailable-image placeholders and mixed naming conventions reduce scan confidence.", "", "## 15 Progress", "", "Progress provides total workouts, monthly count, time, records, volume, best PR, dominant group, adherence, weight trend, stagnation risk, recommendation and chart/measurement/record tabs. Low-data interpretation is real but numeric zeros dominate early scanning; longitudinal usefulness is not established.", "", "## 16 Nutrition", "", "Nutrition provides daily state, macros/recommendation, meal-plan and logging/generation affordances. It is operationally rendered and screenshot-backed in both mobile and desktop. No food log or plan generation write was executed; no clinical judgement is made.", "", "## 17 Gamification", "", "Achievements exposes level/XP/streak/achievement/history surfaces. The feature is real and readable; whether it motivates rather than decorates requires longitudinal observation.", "", "## 18 AI personalization and trust", "", "Trust is `FAIR`: explicit AI CTA, profile proposal and broad rationale support disclosure/control. Inputs-used summary, result rationale, uncertainty, regenerate/edit/undo, wait, cost and error behavior were not safely observable."]
    lines += ["", "## 19 Application shell", "", "Desktop: persistent sidebar, active route, collapse, brand, theme/language/account controls. Mobile: compact top bar/hamburger and preference controls. Shell coherence is a strength; mobile workflow interruption is the trade-off.", "", "## 20 Primary workspaces", md_table(["WORKSPACE","PRIMARY_ACTION","DENSITY","MOBILE","DESKTOP"], [["Dashboard","Start/resume","Medium/high","Readable but tall","Strong action hub"],["Workout","Mark/finish","High/repeated","Long scroll","Full session but dense"],["Progress","Review recommendation","Medium","Cards stack","KPI clear"],["Nutrition","Log/generate","Medium","Vertical","Readable"],["Exercises","Search/filter","High","Filters consume fold","Virtualized scan"],["Achievements","Review","Medium","Stacked","Compact"]]), "", "## 21 Viewport economy", md_table(["VIEWPORT","PRIVATE REPRESENTATION","OBSERVATION"], [["1920×1080","Workout","Wide session; repetition persists"],["1440×900","Six+ private routes","Exact desktop captures"],["1366×768","Dashboard","Short height exposes chrome"],["1024×768","Generator","Tablet width"],["768×1024","Exercises","Portrait tablet density"],["430×932","Six private routes","Mobile auth coverage"],["390×844","Seven private routes","Core mobile execution coverage"]])]
    lines += ["", "## 22 Action hierarchy", "", "Dashboard action hub and workout primary controls are visually clear. Delete plan is present as a competing destructive control in review but separate from start. In execution, Mark and Rest are clear per row, yet no persistent next action exists. Disabled/loading/finish states need controlled interaction coverage.", "", "## 23 System states", md_table(["STATE","WHAT HAPPENS","UNDERSTANDING","NEXT ACTION"], r["system_states"]), "", "## 24 Error recovery", "", "Successful auth/API/session recovery is current. The raw `Failed to fetch` path is historical context, not newly induced evidence; F-02 remains `NOT_RETESTED`. Workout exit/keep draft is explicit. Retry, timeout, offline, session-expiry and backend-unavailable paths require a safe fixture.", "", "## 25 Responsive", "", "Private routes stack and remain legible at 390/430 widths. The main task risk is vertical/contextual rather than horizontal overflow. Progress/nutrition require deeper scroll; exercises spend the first mobile viewport on filters, an acceptable discovery trade-off that should retain a compact result signal.", "", "## 26 Light and dark", "", "Private dashboard, generator, exercises, progress, nutrition, achievements and workout execution are represented in light/dark combinations. Dark has stronger brand confidence; light preserves readability/hierarchy.", "", "## 27 Accessibility", "", "AX evidence exposes named shell, form, heading, button and dialog controls. Repeated workout textboxes are not consistently specific in the AX tree; visual grouping carries semantics that assistive technology needs explicitly. The composed private accessibility tool did not return a material authenticated report and is recorded as a compatibility gap.", "", "## 28 Internationalization", "", "Private visible copy changes ES/EN. The English state retains `html lang=es` because the layout hardcodes Spanish while language context updates visible copy/localStorage. This is a semantic metadata gap, not a blanket untranslated-copy claim.", "", "## 29 Premium surface", "", "The dark navy shell, copper mark, orange CTA and modern typography create a strong base. Premium quality is held back by mobile workout density, repeated cards, unavailable imagery and public accent fragmentation.", "", "## 30 Anti-template and memorability", "", "Impulso reads as a recognizable fitness product because of Momentum Fitness, exercise-specific data and workout controls. Dashboard card patterns are conventional SaaS; the next premium opportunity is a distinctive focused workout canvas, not more decorative cards."]
    lines += ["", "## 31 Historical regression matrix", md_table(["ID","TITLE","OLD SEV","OLD EVIDENCE","CURRENT STATUS","CURRENT ID","CURRENT SEV","CURRENT EVIDENCE","CHANGE","NOTES"], r["historical_matrix"]), "", "## 32 Scorecards"]
    for key, rows in r["scorecards"].items():
        lines += ["", f"### {key}", md_table(["DIMENSION","RATING","BASIS"], rows)]
    lines += ["", "## 33 What works well", md_table(["CAPABILITY","EVIDENCE","WHY_IT_WORKS","DO_NOT_BREAK"], r["what_works_well"]), "", "## 34 Product UX/access findings"]
    for x in f:
        lines += ["", f"### {x['id']} · {x['title']}", md_table(["FIELD","VALUE"], [[k, x.get(k)] for k in ["category","finding_scope","surface","journey","screen","user_type","task_criticality","friction_type","severity","priority","evidence_level","browser_environment","evidence","frequency","current_behavior","root_ux_cause","why_it_matters","user_impact","recommended_change","why_this_change","expected_benefit","effort","risk","quick_win","dependencies","do_not_break","historical_id","change_class","implementation_guidance"]])]
    lines += ["", "## 35 Engineering/compliance scope", "", "No engineering-support or compliance finding is promoted without current evidence. Runtime CORS is documented as an already-remediated external configuration dependency. Admin was safety-blocked. No product-code change is part of this audit.", "", "## 36 Quick wins", md_table(["ID","CHANGE","PHASE","LINK","EFFORT"], r["quick_wins"]), "", "## 37 Structural opportunities", md_table(["ID","OPPORTUNITY","PHASE","LINK","RATIONALE"], r["structural_opportunities"]), "", "## 38 Roadmap", md_table(["PHASE","WORK","SOURCE"], [["P0 — access","Keep canonical auth/CORS validation; add controlled error fixture","B01-B05/F-01/F-02"],["P1 — core","Focused workout + public/social entry decisions","UX-01/UX-08/UX-09"],["P2 — recovery","Retry, low-data context, document lang","UX-06/B07"],["P3 — mobile workout","Set progression, safe exit/resume, drawer strategy","UX-01/02/03"],["P4 — onboarding/AI","Safe fixture, inputs/rationale/regenerate/undo","UX-05/H-09"],["P5 — feedback","Progress/nutrition/XP weekly loop","UX-07/H-12/H-13"],["P6 — premium","Copper token, media/motion/accessibility polish","UX-04/UX-11"]]), "", "## 39 DO_NOT_BREAK", "", "\n".join(f"- {x[0]} — {x[2]}" for x in r["what_works_well"])]
    lines += ["", "## 40 Evidence coverage", md_table(["METRIC","RESULT","GATE"], [["Browser evidence",m["browser_evidence_count"],">=60 target"],["Useful screenshots",m["useful_screenshot_count"],">=40 target"],["Full journeys",m["full_core_journeys"],">=15 target"],["Private surfaces",m["authenticated_surfaces_reviewed"],">=8 target"],["Mobile private surfaces",m["mobile_authenticated_surfaces"],">=4 target"],["Desktop private surfaces",m["desktop_authenticated_surfaces"],">=6 target"],["Viewports",", ".join(m["viewports_represented"]),"7 represented"],["Themes/locales","light + dark / es + en","PASS"]]), "", "### Screenshot index", md_table(["ID","ENV","SURFACE","JOURNEY","VIEWPORT","THEME","LOCALE","URL","DESCRIPTION"], [[e["id"],e.get("environment"),e.get("surface"),e.get("journey"),e.get("viewport"),e.get("theme"),e.get("locale"),e.get("url"),e.get("description")] for e in r["evidence"] if e.get("type")=="SCREENSHOT"]), "", "## 41 Tool compatibility", "", "The previous native CUA path supplied real authorized Chrome accessibility evidence but no screenshot export. The isolated agent-browser session supplied current production screenshots and route measurements. Static runtime output is code/context only. The private composed accessibility tool produced no material authenticated element report, so coverage is not claimed.", "", "## 42 Limitations", "", "\n".join(f"- {x}" for x in r["limitations"]), "", "## 43 Final comparative answer", md_table(["QUESTION","ANSWER"], [["Better/igual/peor","Better on access and private evidence; not fully end-to-end because writes were bounded."],["Historical fixes","F-01 VERIFIED_FIXED after CORS runtime remediation."],["Still present","F-04/F-05/F-06/F-07/F-09; F-02 NOT_RETESTED; H-10-H-13 partial."],["Canonical operational","Yes: login/session/dashboard/API/refresh/logout pass."],["Core tasks","Auth, browse, review and preferences covered; generation/completion/logging/profile writes partial or blocked."],["Mobile workout","Partly supported, not certified: controls visible, but long scroll/repeated context."],["AI trust","Moderate foundation; result rationale/reversibility incomplete."],["Progress/nutrition","Useful current state; longitudinal/action loop open."],["Premium","Strong foundation, not fully premium until mobile/focus/density/palette improve."],["Highest return","Focused mobile workout workspace plus accessible set semantics."]]), "", "**FINAL_RESULT:** `PASS_WITH_JUSTIFIED_GAPS` — depth gates met; explicit safety, fixture and tool limitations remain."]
    (AUDIT_DIR/f"{STEM}.md").write_text("\n".join(lines)+"\n")


def write_html(r: dict[str, Any]) -> None:
    m = r["metadata"]
    section_titles = ["Executive assessment","What changed","Methodology and depth gap","Surface and product model","Promise versus observed","Users, tasks and journeys","Screen and experience maps","Workout generation and execution","Mobile ergonomics","Progress, nutrition and gamification","Shell, viewport, theme, i18n and access","Historical matrix and scorecards","Findings, strengths and roadmap","Evidence, limitations and final answer"]
    nav = "".join(f"<a href='#s{i+1:02d}'>{i+1:02d}</a>" for i in range(len(section_titles)))
    fcards = "".join(f"<article class='finding'><div><b>{esc(x['id'])}</b><span class='sev {x['severity'].lower()}'>{esc(x['severity'])} · {esc(x['priority'])}</span></div><h3>{esc(x['title'])}</h3><p>{esc(x['evidence'])}</p><dl><dt>Scope</dt><dd>{esc(x['finding_scope'])}</dd><dt>Journey</dt><dd>{esc(x['journey'])}</dd><dt>Impact</dt><dd>{esc(x['user_impact'])}</dd><dt>Change</dt><dd>{esc(x['recommended_change'])}</dd></dl></article>" for x in r["findings"])
    figs = []
    for e in r["evidence"]:
        if e.get("type") != "SCREENSHOT" or not e.get("path"):
            continue
        image_path = Path(e["path"])
        if not image_path.is_absolute():
            image_path = ROOT / image_path
        rel = image_path.relative_to(AUDIT_DIR).as_posix()
        figs.append(f"<figure><img src='{rel}' alt='{esc(e['description'])}'><figcaption><b>{esc(e['id'])}</b> · {esc(e['environment'])} · {esc(e['surface'])} · {esc(e['journey'])} · {esc(e['viewport'])} · {esc(e['theme'])}/{esc(e['locale'])}<br>{esc(e['url'])}<br>{esc(e['description'])}</figcaption></figure>")
    sections = []
    metric_rows = [("Browser records",m["browser_evidence_count"]),("Screenshots",m["useful_screenshot_count"]),("Journeys",m["full_core_journeys"]),("Private surfaces",m["authenticated_surfaces_reviewed"])]
    metric_html = "".join(f"<div class='metric'><b>{esc(k)}</b><strong>{esc(v)}</strong></div>" for k,v in metric_rows)
    sections.append("<section id='s01'><h2>01 Executive assessment</h2><div class='hero-grid'><div><h3>Verdict</h3><p>Better access and materially deeper private-product evidence than the previous artifact. Status is <b>PASS_WITH_JUSTIFIED_GAPS</b> because safe boundaries prevent writes and fixture-sensitive tests.</p></div>" + metric_html + html_table(["Question","Answer"], [["BIGGEST FRICTION","Long repeated workout set ledger without persistent focus"],["BIGGEST QUICK WIN","Per-set accessible names/fieldsets"],["BIGGEST STRUCTURAL","Focused mobile workout workspace"],["BIGGEST AI TRUST","Inputs/rationale/regenerate/undo"],["OVERALL","Good foundation; fair-to-good active fitness UX"]]) + "</section>")
    sections.append("<section id='s02'><h2>02 What changed</h2><p>The prior seven screenshots and private preview record are preserved with context. Current production adds 55 useful screenshots, explicit viewports, language/theme variants and route-specific evidence. No product source changed.</p>" + html_table(["Area","Current depth","Remediation"], [[x[0],x[1],x[6]] for x in r["depth_gap_matrix"]]) + "</section>")
    sections.append("<section id='s03'><h2>03 Methodology and depth gap</h2><p>Contractual skill v1.5.0 wins over v1.4.0 manifest/runtime metadata. Browser evidence is PRODUCTION. `COMPLETED != COVERED` and blocked writes are not scored as failures.</p>" + html_table(["Field","Value"], [[k,v if not isinstance(v,list) else ', '.join(v)] for k,v in r["depth_parity_with_talent"].items()]) + "</section>")
    sections.append("<section id='s04'><h2>04 Surface and product model</h2>" + html_table(["Field","Result","Source"], [["Primary","APPLICATION","Private route evidence"],["Secondary","LANDING_PAGE","/landing"],["Platform","PWA","Manifest; offline unknown"],["Domain","FITNESS","Workout/progress/nutrition/exercise"],["Auth/CORS","PASS","B01-B05"]]) + "</section>")
    sections.append("<section id='s05'><h2>05 Promise versus observed</h2>" + html_table(["Promise","Observed","Evidence","Confidence"], [["Personalization","Proposal/rationale visible; result control open","E14/E56","MEDIUM"],["Workout execution","12-set session; long-form concern","E26/E35/E60","HIGH"],["Progress","KPIs/recommendation/charts; low data","E16/E58","HIGH"],["Nutrition","Daily/plan/log affordances; write blocked","E17/E59","MEDIUM"],["Premium","Dark/copper base; palette/density gaps","E01-E04/E55/E60","MEDIUM"]]) + "</section>")
    sections.append("<section id='s06'><h2>06 Users, tasks and journeys</h2>" + html_table(["User type","Goal","Entry","Workspace","Next","Recovery"],r["user_types"]) + html_table(["Task","Class","Criticality","Coverage"], [[x[1],x[2],x[3],x[4]] for x in r["tasks"]]) + html_table(["Journey","Route","Coverage","Screenshots"], [[j.get("name"),j.get("route"),j.get("coverage"),', '.join(j.get("screenshot_reference",[]))] for j in r["journeys"]]) + "</section>")
    sections.append("<section id='s07'><h2>07 Screen and experience maps</h2>" + html_table(["Screen","Purpose","Primary","Entry","Exit","Recovery"], [[x[0],x[1],x[2],x[6],x[7],x[8]] for x in r["screen_map"]]) + html_table(["Stage","Entry","Goal","Action","Friction","Result"], [[x[0],x[1],x[2],x[3],x[5],x[6]] for x in r["experience_map"]]) + "</section>")
    sections.append("<section id='s08'><h2>08 Workout generation and execution</h2><p>Generation exposes profile proposal, 40+ rationale, controls and AI CTA; safe write boundary prevents result/regenerate/undo observation. Review exposes start and delete. Execution exposes four exercises, 12 sets, reps/load/RIR/RPE/rest, mark/rest, progress, notes and exit/finish. At 390×844 only the first exercise is above fold; later sets require scroll.</p>" + html_table(["Measure","Observed","Implication"], [["Sets","12","Repeated scan"],["Scroll","Later groups below fold","High divided attention"],["Timer","Rest card visible; live timer not activated","Later visibility unknown"],["Next action","Mark local to row","No persistent focus"],["Completion","Not invoked","Blocked write"]]) + "</section>")
    sections.append("<section id='s09'><h2>09 Mobile ergonomics</h2><p>Touch controls are visible and the shell is responsive, but the hamburger/drawer creates a context switch and the workout page is a long form. The evidence supports `PARTLY_SUPPORTED`, not a real-workout certification.</p>" + html_table(["Dimension","Rating","Basis"],r["scorecards"]["MOBILE_WORKOUT"]) + "</section>")
    sections.append("<section id='s10'><h2>10 Progress, nutrition and gamification</h2><p>Progress provides KPIs, adherence, recommendation, charts and low-data interpretation. Nutrition provides daily state and plan/log actions. Gamification provides level/XP/achievement/history. All are real renderable surfaces; longitudinal utility and cross-surface loop remain open.</p>" + html_table(["Workspace","Primary","Density","Mobile","Desktop"], [["Dashboard","Start/resume","Medium/high","Readable/tall","Strong hub"],["Workout","Mark/finish","High","Long scroll","Dense"],["Progress","Review action","Medium","Stacked","Clear KPIs"],["Nutrition","Log/generate","Medium","Vertical","Readable"],["Exercises","Search/filter","High","Filters consume fold","Virtualized"],["Achievements","Review","Medium","Stacked","Compact"]]) + "</section>")
    sections.append("<section id='s11'><h2>11 Shell, viewport, theme, i18n and access</h2>" + html_table(["Viewport","Private representation","Observation"], [["1920×1080","Workout","Wide but repetitive"],["1440×900","Core routes","Desktop baseline"],["1366×768","Dashboard","Short chrome tradeoff"],["1024×768","Generator","Tablet"],["768×1024","Exercises","Portrait density"],["430×932","Private routes","Mobile"],["390×844","Private routes","Core workout"]]) + "<p>Private light/dark and ES/EN captures are present. Visible English copy changes but document language remains Spanish. AX exposes named controls, while repeated workout inputs lack specific names. Private composed accessibility tool is a compatibility gap.</p></section>")
    sections.append("<section id='s12'><h2>12 Historical matrix and scorecards</h2>" + html_table(["ID","Status","Current evidence","Change"], [[x[0],x[4],x[7],x[8]] for x in r["historical_matrix"]]) + "<h3>Application</h3>" + html_table(["Dimension","Rating","Basis"],r["scorecards"]["APPLICATION"]) + "<h3>Landing / AI / Premium</h3>" + html_table(["Dimension","Rating","Basis"],r["scorecards"]["LANDING"]+r["scorecards"]["AI_TRUST"]+r["scorecards"]["PREMIUM"]) + "</section>")
    sections.append("<section id='s13'><h2>13 Findings, strengths and roadmap</h2><div class='finding-grid'>" + fcards + "</div><h3>What works well</h3>" + html_table(["Capability","Evidence","Why","Do not break"],r["what_works_well"]) + "<h3>Roadmap</h3>" + html_table(["Phase","Work","Source"],r["structural_opportunities"]+r["quick_wins"]) + "</section>")
    sections.append("<section id='s14'><h2>14 Evidence, limitations and final answer</h2>" + html_table(["Metric","Result","Gate"], [["Browser records",m["browser_evidence_count"],">=60"],["Useful screenshots",m["useful_screenshot_count"],">=40"],["Full journeys",m["full_core_journeys"],">=15"],["Mobile private",m["mobile_authenticated_surfaces"],">=4"],["Desktop private",m["desktop_authenticated_surfaces"],">=6"],["Themes/locales","light+dark / es+en","PASS"]]) + "<ul>" + "".join(f"<li>{esc(x)}</li>" for x in r["limitations"]) + "</ul>" + html_table(["Question","Answer"], [["Comparative","Better on access/private evidence; writes remain bounded"],["Canonical","Operational for login, API, dashboard, refresh and logout"],["Mobile workout","Partly supported, not certified"],["AI","Moderate foundation; reversibility incomplete"],["Progress/nutrition","Useful current states; longitudinal loop open"],["Premium","Strong base; mobile/density/palette gaps"],["Next return","Focused workout workspace and set semantics"]]) + "<p class='final'><b>FINAL_RESULT: PASS_WITH_JUSTIFIED_GAPS</b></p></section>")
    body = "".join(sections) + "<section id='evidence'><h2>Evidence screenshots</h2><p>Every screenshot has an evidence ID, environment, surface, journey, viewport, theme, locale, URL and observed behavior. No orphan screenshots are included.</p><div class='shots'>" + "".join(figs) + "</div></section>"
    css = """<style>:root{--ink:#15223d;--muted:#60708a;--orange:#ee7935;--navy:#071126;--line:#d8e0eb;--soft:#f5f7fb}*{box-sizing:border-box}body{margin:0;background:#eaf0f6;color:var(--ink);font:14px/1.5 Inter,system-ui,sans-serif}.page{max-width:1440px;margin:auto;background:#fff;box-shadow:0 0 60px #0611261a}.cover{padding:74px 82px 58px;color:#fff;background:radial-gradient(circle at 70% 12%,#ef7b3580,transparent 28%),linear-gradient(135deg,#050a1a,#0e1c3e 65%,#28162e)}.kicker{letter-spacing:.22em;text-transform:uppercase;color:#ffbb91;font-size:12px;font-weight:700}h1{font-size:58px;line-height:1.03;max-width:820px;margin:28px 0 16px}.cover p{font-size:19px;color:#d7e0ef;max-width:760px}.meta-grid,.hero-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:36px}.meta,.metric{padding:14px;border:1px solid #ffffff2d;border-radius:14px;background:#ffffff0d}.meta b,.metric b{display:block;color:#ffbd91;font-size:10px;letter-spacing:.12em;text-transform:uppercase}.meta span{display:block;margin-top:5px;font-size:13px}.metric strong{display:block;font-size:28px;margin-top:4px}.nav{position:sticky;top:0;z-index:4;padding:11px 82px;background:#061126}.nav a{color:#cbd4e2;text-decoration:none;padding:4px 8px;font-size:12px}.nav a:hover{background:#ffffff15;color:#fff}main{padding:38px 82px 0}section{scroll-margin-top:50px;margin-bottom:30px}section:last-child{margin-bottom:0}h2{margin:0 0 16px;padding-bottom:8px;border-bottom:3px solid var(--orange);font-size:29px}h3{margin:20px 0 8px}p{color:#33445e}.table-wrap{overflow-x:auto;margin:13px 0 20px}table{border-collapse:collapse;width:100%;font-size:12px}th{background:#0b1933;color:#fff;text-align:left;padding:8px;white-space:nowrap;vertical-align:top}td{border:1px solid var(--line);padding:7px;vertical-align:top;min-width:80px}tr:nth-child(even) td{background:var(--soft)}.finding-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:15px}.finding{border:1px solid var(--line);border-radius:15px;padding:16px;background:linear-gradient(#fff,#f7f9fc);break-inside:avoid}.finding>div{display:flex;justify-content:space-between}.sev{font-size:10px;border-radius:15px;background:#e4ebf3;padding:3px 7px}.sev.high{background:#ffedd5;color:#c2410c}.sev.critical{background:#fee4e2;color:#b42318}.finding p,.finding dd{font-size:12px}.finding dl{display:grid;grid-template-columns:65px 1fr;gap:4px}.finding dt{font-weight:700;color:var(--muted)}.finding dd{margin:0}details{border:1px solid var(--line);padding:8px;border-radius:8px}.shots{display:grid;grid-template-columns:repeat(2,1fr);gap:17px}figure{margin:0;padding:8px;border:1px solid var(--line);border-radius:11px;background:#fafbfd;break-inside:avoid}figure img{display:block;width:100%;height:auto;border-radius:6px}figcaption{font-size:11px;color:var(--muted);padding:7px 2px}.final{border-left:6px solid var(--orange);background:#fff7ed;padding:14px;font-size:16px}footer{padding:26px 82px;background:#061126;color:#c5d0e2;font-size:12px}@media print{.nav{display:none}.shots{display:block}figure{break-inside:avoid}figure img{max-height:105mm;object-fit:contain}}@media(max-width:850px){.cover,main,footer{padding-left:22px;padding-right:22px}h1{font-size:40px}.meta-grid,.hero-grid,.finding-grid,.shots{grid-template-columns:1fr}.nav{padding:10px 16px}table{font-size:10px}}</style>"""
    meta_cells = "".join(f"<div class='meta'><b>{esc(k)}</b><span>{esc(v if not isinstance(v,list) else ', '.join(v))}</span></div>" for k,v in [("Date/status",f"{m['date']} · {m['status']}"),("Head/branch",f"{m['current_head'][:10]} · {m['branch']}"),("Skill",f"{m['skill_contract_version']} / {m['skill_runtime_version']} runtime"),("Surface",f"{m['primary_surface']} + {', '.join(m['secondary_surfaces'])}"),("Canonical",m['canonical_frontend_url']),("Environment","PRODUCTION"),("Evidence",m['browser_evidence_count']),("Historical",m['old_finding_count'])])
    html_doc = f"<!doctype html><html lang='en'><head><meta charset='utf-8'><title>Anclora Impulso — Deep UX/UI Product Re-Audit</title>{css}</head><body><div class='page'><header class='cover'><div class='kicker'>Anclora Impulso · Deep remediation</div><h1>UX/UI Product Re-Audit</h1><p>Current product · current code · current deployment · current browser · current findings.</p><div class='meta-grid'>{meta_cells}</div></header><nav class='nav'>{nav}</nav><main>{body}</main></div></body></html>"
    (AUDIT_DIR/f"{STEM}.html").write_text(html_doc)


if __name__ == "__main__":
    main()
